function validateHeaderContent(content) {
  if (typeof content !== 'string' || content.trim() === '') {
    console.warn('Invalid header content:', content);
    return false;
  }
  return true;
}

function storeInfoInHeader(infoType, infoContent, header) {
  try {
    if (infoType === 'lang' && validateHeaderContent(infoContent)) {
      header['Accept-Language'] = infoContent;
    } else if (infoType === 'encoding' && validateHeaderContent(infoContent)) {
      header['Accept-Encoding'] = infoContent;
    } else if (infoType === 'cache' && validateHeaderContent(infoContent)) {
      header['Cache-Control'] = infoContent;
    }
  } catch (error) {
    console.error('Error storing header:', error);
    return header;
  }
  return header;
}

